<script lang="ts">
 import { onMount } from 'svelte';import { base } from '$app/paths';import { db } from '$lib/db';import { createId } from '$lib/id';import type { PaletteSet } from '$lib/types';
 let sets=$state<PaletteSet[]>([]),name=$state(''),colorName=$state(''),hex=$state('#2c5a4a'),colors=$state<{name:string;hex:string}[]>([{name:'Forest green',hex:'#2c5a4a'}]),error=$state('');
 async function refresh(){sets=await db.paletteSets.toArray();}
 onMount(()=>{void refresh();});
 function addColor(){if(!/^#[\da-f]{6}$/i.test(hex)){error='Enter a valid 6-digit hex color.';return;}colors=[...colors,{name:colorName.trim()||hex.toUpperCase(),hex:hex.toUpperCase()}];colorName='';error='';}
 async function create(){if(!name.trim()||!colors.length){error='Give this set a name and at least one color.';return;}await db.paletteSets.add({id:createId(),name:name.trim(),colors});name='';colors=[];error='';await refresh();}
 async function remove(id:string){if(confirm('Delete this color set?')){await db.paletteSets.delete(id);await refresh();}}
</script>
<div class="app palettes-page"><header class="topbar"><a class="brand" href={`${base}/`}><span class="brand-mark">✳</span>Skepanion</a><nav class="nav"><a href={`${base}/`}>Drawings</a><a href={`${base}/monthly`}>Monthly</a></nav></header><p class="eyebrow">Your art supplies</p><h1>My colors</h1><p class="muted">Add colors from your paint or pencil set. We’ll suggest approximate mixes for each stage color.</p>
<section class="section card palette-builder"><div class="builder-heading"><span class="builder-step">01</span><div><h2>Create a color set</h2><p class="muted">Add the colors you have on hand.</p></div></div><div class="field"><label for="setname">Set name</label><input id="setname" bind:value={name} placeholder="My 24 colored pencils"/></div><div class="row color-entry"><div class="field color-name-field"><label for="colorname">Color name</label><input id="colorname" bind:value={colorName} placeholder="Ultramarine blue"/></div><div class="field color-picker-field"><label for="colorhex">Swatch</label><input id="colorhex" type="color" bind:value={hex}/></div><button class="button secondary" onclick={addColor}>Add color</button></div>{#if colors.length}<div class="color-chips">{#each colors as c,i}<span class="color-chip"><i style={`background:${c.hex}`}></i><span>{c.name}</span><button aria-label={`Remove ${c.name}`} onclick={()=>colors=colors.filter((_,n)=>n!==i)}>×</button></span>{/each}</div>{/if}<button class="button" onclick={()=>void create()}>Save color set</button>{#if error}<p role="alert" class="form-error">{error}</p>{/if}</section>
<section class="section"><h2>Saved sets</h2>{#if !sets.length}<div class="card empty-card"><p class="muted">No sets yet. Create one when you’re ready to compare your extracted colors with your supplies.</p></div>{:else}<div class="grid">{#each sets as set}<article class="card"><h2>{set.name}</h2><p class="muted">{set.colors.length} colors</p><div class="row">{#each set.colors as c}<span title={c.name} style={`display:inline-block;width:24px;height:24px;border-radius:7px;background:${c.hex}`}></span>{/each}</div><div style="margin-top:14px"><button class="button danger" onclick={()=>void remove(set.id)}>Delete set</button></div></article>{/each}</div>{/if}</section></div>
